SELECT CASE WHEN YEAR(launch_date) < 2024 THEN 'before_2024' WHEN YEAR(launch_date) = 2024 THEN '2024' ELSE 'after_2024' END launch_cohort, CASE WHEN cost >= 720 THEN 'high' WHEN cost >= 150 THEN 'mid' ELSE 'low' END cost_bucket, SUM(CASE WHEN brand = 'Globex' THEN 1 ELSE 0 END) globex_count FROM products WHERE brand = 'Globex' AND (supplier_id IN (14, 17, 32) OR brand IN ('Umbrella', 'Globex', 'Initech')) GROUP BY launch_cohort, cost_bucket ORDER BY launch_cohort
